/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The PurchTabel form extension
/// </summary>
[ExtensionOf(FormStr(PurchTable))]
final class METPurchTableForm_Extension
{
    [DataSource]
    class METPurchTable
    {
        /// <summary>
        /// Write method COC
        /// </summary>
        public void write()
        {
            FormDataSource formDS = this;
            METPurchTable METPurchTable = formDS.cursor();

            if (METPurchTable.PurchTable)
            {
                next Write();
            }
        }

        /// <summary>
        /// Validate write method COC
        /// </summary>
        /// <returns>boolean</returns>
        public boolean validatewrite()
        {
            boolean ret = true;
            FormDataSource formDS = this;
            METPurchTable METPurchTable = formDS.cursor();

            if (METPurchTable.PurchTable)
            {
                ret = next validatewrite();
            }

            return ret;
        }
    }

    [DataSource]
    class PurchTable
    {
        /// <summary>
        /// Write method COC
        /// </summary>
        void write()
        {
            next write();

            FormDataSource fds = this;
            FormDataSource fdsMETPurchTable = fds.formRun().dataSource(formDataSourceStr(SalesTable, METPurchTable));

            METPurchTable METPurchTable;
            if (fdsMETPurchTable)
            {
                PurchTable PurchTable = fds.cursor();
                METPurchTable = fdsMETPurchTable.cursor();
                PurchTable.packMETPurchTable(METPurchTable);
                METPurchTable.SysExtensionSerializerExtensionMap::insertAfterBaseTable(PurchTable);
            }

        }
    }

}
